src/interfaces/IWIF.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/// @notice $WIF is a plain OpenZeppelin ERC20Burnable: `burn` / `burnFrom` are real burns
///         (totalSupply decreases). Everything in Flatland that "burns" uses these.
interface IWIF is IERC20 {
    function burn(uint256 value) external;
    function burnFrom(address account, uint256 value) external;
}

src/interfaces/IEntropy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @notice Block-hash source used for the verifiable future-block draw.
/// @dev On Robinhood Chain (Arbitrum Nitro) `block.number` is the *L1* estimate and
///      `blockhash` is not the L2 hash, so the production implementation reads the
///      `ArbSys` precompile. Local/anvil runs use `LocalEntropy`.
interface IEntropy {
    /// @return the current block counter in the unit `hashOf` understands.
    function currentBlock() external view returns (uint256);
    /// @return hash of block `n`, or 0 if `n` is not yet mined / older than 256 blocks.
    function hashOf(uint256 n) external view returns (bytes32);
}

src/interfaces/IOutcomeExecutor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

/// @notice An onchain action bound to an election. Called once by the Flatland hub when the
///         election is finalized. Executors MUST check `msg.sender == flatland` and that the
///         election id is the one they expect. A revert never blocks finalization.
interface IOutcomeExecutor {
    /// @param id      election id
    /// @param winner  winning option index (lowest index wins ties)
    /// @param tally   final per-option vote counts (1 wallet = 1 vote, after sybil collapse)
    function onFinalize(uint256 id, uint8 winner, uint256[] calldata tally) external;
}

src/DepositBox.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.26;

import {IWIF} from "./interfaces/IWIF.sol";

/// @notice Per-(election, option) deposit address. Voters "just send 1 WIF" to it: no wallet connect,
///         nothing to sign. Anyone may later `sweep` through the hub, which burns the balance.
/// @dev Deployed as an EIP-1167 clone at a CREATE2 address, so the address is known (and shown in the
///      UI/QR) before the contract exists. Immutables live in the implementation and are shared by clones.
contract DepositBox {
    address public immutable hub;
    IWIF public immutable wif;

    error OnlyHub();

    constructor(address hub_, address wif_) {
        hub = hub_;
        wif = IWIF(wif_);
    }

    /// @notice Burn everything held. Hub-only so burn totals are attributed to the right election.
    function burnAll() external returns (uint256 amount) {
        if (msg.sender != hub) revert OnlyHub();
        amount = wif.balanceOf(address(this));
        if (amount > 0) wif.burn(amount);
    }
}

